import React, { useState, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { apiFetch } from '../../lib/runtime';

interface ImageModel {
    id: string;
    label: string;
    provider: string;
}

interface Props {
    models: { kie: ImageModel[]; remote: ImageModel[] };
}

interface GeneratedResult {
    id: string;
    prompt: string;
    urls: string[];
    provider: string;
    model: string;
    timestamp: string;
}

const PROVIDER_LABELS: Record<string, string> = {
    'kie':         'KIE.ai',
    'chatgpt-web': 'ChatGPT Images 2.0',
    'gemini-web':  'Gemini'
};

const PROVIDER_COLOR: Record<string, string> = {
    'kie':         'var(--cyan-glow)',
    'chatgpt-web': 'var(--gold-solar)',
    'gemini-web':  '#4285f4'
};

export default function VisualSynthesisLane({ models }: Props) {
    const [prompt, setPrompt]           = useState('');
    const [selectedModel, setSelectedModel] = useState<ImageModel | null>(null);
    const [kieExpanded, setKieExpanded] = useState(true);
    const [remoteExpanded, setRemoteExpanded] = useState(false);
    const [results, setResults]         = useState<GeneratedResult[]>([]);
    const [generating, setGenerating]   = useState(false);
    const [error, setError]             = useState<string | null>(null);

    const kieModels    = models.kie?.length ? models.kie    : DEFAULT_KIE_MODELS;
    const remoteModels = models.remote?.length ? models.remote : DEFAULT_REMOTE_MODELS;

    const generate = useCallback(async () => {
        if (!prompt.trim() || !selectedModel) return;
        setGenerating(true);
        setError(null);
        try {
            if (selectedModel.provider === 'kie') {
                const res = await apiFetch('/api/neural/images/generate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        prompt,
                        modelId: selectedModel.id,
                        waitForCompletion: true
                    })
                });
                const data = await res.json();
                if (!res.ok) throw new Error(data.error || 'Generation failed');
                const urls: string[] = data.task?.resultUrls || data.resultUrls || [];
                setResults(prev => [{
                    id: Date.now().toString(),
                    prompt,
                    urls,
                    provider: 'kie',
                    model: selectedModel.label,
                    timestamp: new Date().toISOString()
                }, ...prev.slice(0, 19)]);
            } else {
                // Remote browser automation — trigger via backend
                const res = await apiFetch('/api/image-gen/browser', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        prompt,
                        modelId: selectedModel.id,
                        provider: selectedModel.provider
                    })
                });
                const data = await res.json();
                if (!res.ok) throw new Error(data.error || 'Browser automation failed');
                const urls: string[] = data.urls || data.resultUrls || [];
                setResults(prev => [{
                    id: Date.now().toString(),
                    prompt,
                    urls,
                    provider: selectedModel.provider,
                    model: selectedModel.label,
                    timestamp: new Date().toISOString()
                }, ...prev.slice(0, 19)]);
            }
        } catch (e: any) {
            setError(e.message || 'Unknown error');
        } finally {
            setGenerating(false);
        }
    }, [prompt, selectedModel]);

    const openInFinder = (_url: string) => {
        apiFetch('/api/execute', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ commandKey: 'OPEN_IMAGES_FOLDER' })
        }).catch(() => {});
    };

    return (
        <div style={{ padding: '4px 0', height: '100%', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 12 }}>
            <div style={{ fontSize: 9, letterSpacing: '0.14em', color: 'var(--gold-solar)', textTransform: 'uppercase', marginBottom: 4 }}>
                Visual Synthesis Lane
            </div>

            {/* Prompt */}
            <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start' }}>
                <textarea
                    value={prompt}
                    onChange={e => setPrompt(e.target.value)}
                    placeholder="Image prompt..."
                    rows={2}
                    style={{
                        flex: 1, background: 'rgba(255,255,255,0.03)',
                        border: '1px solid rgba(159,232,115,0.15)',
                        color: 'var(--silver-albedo)',
                        fontFamily: 'JetBrains Mono, monospace',
                        fontSize: 12, padding: '6px 10px', resize: 'none', outline: 'none',
                        borderRadius: 2
                    }}
                />
                <button
                    onClick={generate}
                    disabled={!selectedModel || !prompt.trim() || generating}
                    style={{
                        background: generating ? 'rgba(159,232,115,0.05)' : 'rgba(159,232,115,0.1)',
                        border: '1px solid rgba(159,232,115,0.3)',
                        color: 'var(--cyan-glow)',
                        fontFamily: 'JetBrains Mono, monospace',
                        fontSize: 11, padding: '6px 14px', cursor: 'pointer',
                        borderRadius: 2, letterSpacing: '0.08em',
                        opacity: (!selectedModel || !prompt.trim()) ? 0.4 : 1
                    }}
                >
                    {generating ? '⟳' : 'Generate'}
                </button>
            </div>

            {/* Model picker — KIE (primary, expanded by default) */}
            <ModelDropdown
                title="KIE.ai Models"
                note="Primary — fastest"
                models={kieModels}
                expanded={kieExpanded}
                onToggle={() => setKieExpanded(p => !p)}
                selected={selectedModel}
                onSelect={setSelectedModel}
                color="var(--cyan-glow)"
            />

            {/* Model picker — Remote */}
            <ModelDropdown
                title="Remote Generation"
                note="Browser automation"
                models={remoteModels}
                expanded={remoteExpanded}
                onToggle={() => setRemoteExpanded(p => !p)}
                selected={selectedModel}
                onSelect={setSelectedModel}
                color="var(--gold-solar)"
            />

            {/* Error */}
            {error && (
                <div style={{ fontSize: 11, color: 'var(--red-fusion)', padding: '4px 8px', background: 'rgba(217,112,72,0.08)', borderLeft: '2px solid var(--red-fusion)' }}>
                    {error}
                </div>
            )}

            {/* Results */}
            {results.length > 0 && (
                <div>
                    <div style={{ fontSize: 9, letterSpacing: '0.12em', color: 'var(--text-dim)', marginBottom: 6, textTransform: 'uppercase' }}>Generated</div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                        {results.map(r => (
                            <div key={r.id} style={{ border: '1px solid rgba(159,232,115,0.1)', borderRadius: 2, overflow: 'hidden' }}>
                                <div style={{ padding: '4px 8px', background: 'rgba(255,255,255,0.02)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <span style={{ fontSize: 10, color: PROVIDER_COLOR[r.provider] || 'var(--text-dim)' }}>
                                        {PROVIDER_LABELS[r.provider] || r.provider} · {r.model}
                                    </span>
                                    <button onClick={() => openInFinder(r.urls[0])} style={{
                                        background: 'none', border: 'none', color: 'var(--text-dim)',
                                        cursor: 'pointer', fontSize: 10
                                    }}>Open in Finder</button>
                                </div>
                                <div style={{ fontSize: 10, color: 'var(--text-dim)', padding: '2px 8px', opacity: 0.6, fontStyle: 'italic' }}>{r.prompt.slice(0, 60)}{r.prompt.length > 60 ? '…' : ''}</div>
                                {r.urls.length > 0 ? (
                                    <div style={{ display: 'flex', gap: 4, padding: 6, flexWrap: 'wrap' }}>
                                        {r.urls.map((url, i) => (
                                            <a key={i} href={url} target="_blank" rel="noreferrer">
                                                <img src={url} alt="Generated" style={{ width: 80, height: 80, objectFit: 'cover', border: '1px solid rgba(159,232,115,0.1)' }}/>
                                            </a>
                                        ))}
                                    </div>
                                ) : (
                                    <div style={{ fontSize: 10, color: 'var(--text-dim)', padding: 8 }}>No preview — check GeneratedContent folder</div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

function ModelDropdown({
    title, note, models, expanded, onToggle, selected, onSelect, color
}: {
    title: string; note: string;
    models: ImageModel[];
    expanded: boolean; onToggle: () => void;
    selected: ImageModel | null;
    onSelect: (m: ImageModel) => void;
    color: string;
}) {
    return (
        <div style={{ border: `1px solid ${color}22`, borderRadius: 2 }}>
            <button onClick={onToggle} style={{
                width: '100%', display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                background: 'none', border: 'none', cursor: 'pointer',
                padding: '6px 10px', color, fontFamily: 'JetBrains Mono, monospace', fontSize: 10,
                letterSpacing: '0.08em', textTransform: 'uppercase'
            }}>
                <span>{title} <span style={{ opacity: 0.5, fontSize: 9 }}>— {note}</span></span>
                <span style={{ opacity: 0.6 }}>{expanded ? '▲' : '▼'}</span>
            </button>
            <AnimatePresence>
                {expanded && (
                    <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.15 }}
                        style={{ overflow: 'hidden' }}>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, padding: '4px 8px 8px' }}>
                            {models.map(m => (
                                <button key={m.id} onClick={() => onSelect(m)} style={{
                                    padding: '3px 10px', fontSize: 10, fontFamily: 'JetBrains Mono, monospace',
                                    background: selected?.id === m.id ? `${color}22` : 'none',
                                    border: `1px solid ${selected?.id === m.id ? color : `${color}33`}`,
                                    color: selected?.id === m.id ? color : 'var(--text-dim)',
                                    cursor: 'pointer', borderRadius: 2,
                                    transition: 'all 0.1s'
                                }}>
                                    {m.label}
                                </button>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

const DEFAULT_KIE_MODELS: ImageModel[] = [
    { id: 'gpt4o-image', label: 'GPT-4o Image', provider: 'kie' },
    { id: 'flux-pro',    label: 'Flux Pro',     provider: 'kie' },
    { id: 'flux-schnell',label: 'Flux Schnell', provider: 'kie' },
    { id: 'ideogram',    label: 'Ideogram V2',  provider: 'kie' },
    { id: 'recraft',     label: 'Recraft V3',   provider: 'kie' }
];

const DEFAULT_REMOTE_MODELS: ImageModel[] = [
    { id: 'chatgpt-images-2', label: 'ChatGPT Images 2.0', provider: 'chatgpt-web' },
    { id: 'dalle3',           label: 'DALL-E 3',           provider: 'chatgpt-web' },
    { id: 'imagen3',          label: 'Imagen 3',           provider: 'gemini-web'  },
    { id: 'veo2',             label: 'Veo 2 (Video)',      provider: 'gemini-web'  }
];

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { apiFetch } from '../../lib/runtime';

interface TermLine { id: number; text: string; type: 'cmd' | 'out' | 'err' | 'info'; }

const CHEATSHEET = [
    {
        category: 'Oracle',
        commands: [
            { cmd: 'oracle <prompt>',       desc: 'Send prompt to Oracle (streaming)' },
            { cmd: 'oracle --council <q>',  desc: 'Aeonic Council deliberation' },
            { cmd: 'oracle status',         desc: 'System health + model status' },
        ]
    },
    {
        category: 'Offload',
        commands: [
            { cmd: 'offload deepseek <task>', desc: 'Route to local Deepseek' },
            { cmd: 'offload qwen <task>',     desc: 'Route to local Qwen' },
            { cmd: 'offload kimi <task>',     desc: 'Route to cloud Kimi' },
            { cmd: 'offload --swarm <task>',  desc: 'Fan-out via Ruflo swarm' },
        ]
    },
    {
        category: 'GitNexus',
        commands: [
            { cmd: 'gitnexus impact <sym>',   desc: 'Blast radius analysis' },
            { cmd: 'gitnexus context <sym>',  desc: 'Full symbol context' },
            { cmd: 'gitnexus query <concept>',desc: 'Semantic code search' },
        ]
    },
    {
        category: 'System',
        commands: [
            { cmd: 'tokens',        desc: 'Show session + weekly token spend' },
            { cmd: 'pm2 status',    desc: 'Backend process status' },
            { cmd: 'pm2 restart all', desc: 'Restart all PM2 processes' },
            { cmd: 'ls .claude/state/', desc: 'Show state files' },
        ]
    }
];

let lineId = 0;

export default function OracleTerminal() {
    const [lines, setLines]     = useState<TermLine[]>([
        { id: lineId++, text: 'NUDIMMUD terminal — type "help" for cheatsheet', type: 'info' },
        { id: lineId++, text: `WS bridge: ${window.location.protocol === 'https:' ? 'wss' : 'ws'}://${window.location.host}/ws/shell`, type: 'info' },
    ]);
    const [input, setInput]     = useState('');
    const [history, setHistory] = useState<string[]>([]);
    const [histIdx, setHistIdx] = useState(-1);
    const [showSheet, setShowSheet] = useState(true);
    const bottomRef = useRef<HTMLDivElement>(null);
    const wsRef     = useRef<WebSocket | null>(null);

    // Connect WebSocket shell
    useEffect(() => {
        try {
            const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            const ws = new WebSocket(`${proto}//${window.location.host}/ws/shell`);
            ws.onmessage = (e) => {
                try {
                    const { type, data } = JSON.parse(e.data);
                    setLines(prev => [...prev, { id: lineId++, text: String(data || ''), type: type === 'stderr' ? 'err' : 'out' }]);
                } catch {
                    setLines(prev => [...prev, { id: lineId++, text: String(e.data), type: 'out' }]);
                }
            };
            ws.onerror = () => setLines(prev => [...prev, { id: lineId++, text: 'WS: connection failed — shell integration unavailable', type: 'err' }]);
            wsRef.current = ws;
            return () => ws.close();
        } catch {
            setLines(prev => [...prev, { id: lineId++, text: 'WS: not available', type: 'info' }]);
        }
    }, []);

    useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [lines]);

    const submit = useCallback(() => {
        const cmd = input.trim();
        if (!cmd) return;
        setLines(prev => [...prev, { id: lineId++, text: `$ ${cmd}`, type: 'cmd' }]);
        setHistory(prev => [cmd, ...prev.slice(0, 49)]);
        setHistIdx(-1);
        setInput('');

        if (cmd === 'help') {
            setShowSheet(true);
            return;
        }
        if (cmd === 'clear') {
            setLines([{ id: lineId++, text: 'Terminal cleared.', type: 'info' }]);
            return;
        }

        if (wsRef.current?.readyState === WebSocket.OPEN) {
            wsRef.current.send(JSON.stringify({ command: cmd }));
        } else {
            // Fallback: HTTP terminal endpoint
            apiFetch('/api/terminal/run', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ command: cmd })
            })
            .then(r => r.json())
            .then(d => {
                const out = d.stdout || '';
                const err = d.stderr || d.error || '';
                if (out) setLines(prev => [...prev, { id: lineId++, text: String(out), type: 'out' }]);
                if (err) setLines(prev => [...prev, { id: lineId++, text: String(err), type: 'err' }]);
            })
            .catch(e => setLines(prev => [...prev, { id: lineId++, text: `Error: ${e.message}`, type: 'err' }]));
        }
    }, [input]);

    const onKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'Enter') { submit(); return; }
        if (e.key === 'ArrowUp') {
            const idx = Math.min(histIdx + 1, history.length - 1);
            setHistIdx(idx);
            setInput(history[idx] || '');
        }
        if (e.key === 'ArrowDown') {
            const idx = Math.max(histIdx - 1, -1);
            setHistIdx(idx);
            setInput(idx < 0 ? '' : history[idx] || '');
        }
    }, [submit, history, histIdx]);

    return (
        <div style={{ display: 'flex', height: '100%', fontFamily: 'JetBrains Mono, monospace', fontSize: 12 }}>
            {/* Output pane */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
                <div style={{ flex: 1, overflowY: 'auto', padding: '8px 12px' }}>
                    {lines.map(l => (
                        <div key={l.id} style={{ lineHeight: 1.6, color: LINE_COLOR[l.type], whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
                            {l.text}
                        </div>
                    ))}
                    <div ref={bottomRef}/>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 12px', borderTop: '1px solid rgba(159,232,115,0.1)' }}>
                    <span style={{ color: 'var(--cyan-glow)', userSelect: 'none' }}>$</span>
                    <input
                        value={input}
                        onChange={e => setInput(e.target.value)}
                        onKeyDown={onKeyDown}
                        style={{
                            flex: 1, background: 'none', border: 'none', outline: 'none',
                            color: 'var(--silver-albedo)', fontFamily: 'inherit', fontSize: 12
                        }}
                        placeholder="command..."
                        autoFocus
                    />
                </div>
            </div>

            {/* Cheatsheet sidebar */}
            {showSheet && (
                <div style={{ width: 260, borderLeft: '1px solid rgba(159,232,115,0.1)', overflowY: 'auto', padding: '8px 12px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                        <span style={{ fontSize: 9, letterSpacing: '0.12em', color: 'var(--gold-solar)', textTransform: 'uppercase' }}>Cheatsheet</span>
                        <button onClick={() => setShowSheet(false)} style={{ background: 'none', border: 'none', color: 'var(--text-dim)', cursor: 'pointer', fontSize: 10 }}>×</button>
                    </div>
                    {CHEATSHEET.map(section => (
                        <div key={section.category} style={{ marginBottom: 12 }}>
                            <div style={{ fontSize: 9, color: 'var(--cyan-glow)', letterSpacing: '0.1em', marginBottom: 4, textTransform: 'uppercase', opacity: 0.7 }}>
                                {section.category}
                            </div>
                            {section.commands.map(c => (
                                <div key={c.cmd} style={{ marginBottom: 4, cursor: 'pointer' }}
                                    onClick={() => setInput(c.cmd.replace(/<[^>]+>/g, ''))}>
                                    <div style={{ color: 'var(--gold-solar)', fontSize: 10 }}>{c.cmd}</div>
                                    <div style={{ color: 'rgba(247,247,247,0.4)', fontSize: 10 }}>{c.desc}</div>
                                </div>
                            ))}
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

const LINE_COLOR: Record<TermLine['type'], string> = {
    cmd:  'var(--cyan-glow)',
    out:  'rgba(247,247,247,0.8)',
    err:  'var(--red-fusion)',
    info: 'rgba(247,247,247,0.35)'
};

import { apiFetchWithTimeout } from './runtime';

export const ORACLE_COMMAND_ENDPOINT = '/api/oracle/command';
export const ORACLE_COMMAND_BUDGETS_MS = {
    deliberationDelay: 150,
    staleSoft: 30_000,
    staleHard: 60_000,
    directHardTimeout: 120_000,
    councilHardTimeout: 180_000
} as const;

export type OracleCommandPhase =
    | 'idle'
    | 'submitted'
    | 'deliberating'
    | 'stale'
    | 'completed'
    | 'failed';

export type OracleCommandSource = 'typed' | 'voice';
export type OracleCommandMode = 'direct' | 'council';
export type OracleStaleLevel = 'soft' | 'hard';

export interface OracleCommandResponse {
    [key: string]: any;
}

export interface OracleCommandState {
    requestId: string | null;
    source: OracleCommandSource | null;
    mode: OracleCommandMode;
    phase: OracleCommandPhase;
    staleLevel: OracleStaleLevel | null;
    command: string;
    response: OracleCommandResponse | null;
    error: string | null;
    submittedAt: number | null;
    settledAt: number | null;
    elapsedMs: number;
}

export interface OracleSubmitOptions {
    command: string;
    source?: OracleCommandSource;
    useCouncil?: boolean;
    modelId?: string;
    signal?: AbortSignal;
}

type OracleCommandListener = (state: OracleCommandState) => void;

const listeners = new Set<OracleCommandListener>();

let state: OracleCommandState = createIdleState();
let requestCounter = 0;
let activeController: AbortController | null = null;
let phaseTimer: number | null = null;
let staleSoftTimer: number | null = null;
let staleHardTimer: number | null = null;
let tickInterval: number | null = null;

function createIdleState(): OracleCommandState {
    return {
        requestId: null,
        source: null,
        mode: 'direct',
        phase: 'idle',
        staleLevel: null,
        command: '',
        response: null,
        error: null,
        submittedAt: null,
        settledAt: null,
        elapsedMs: 0
    };
}

function cloneState(current: OracleCommandState): OracleCommandState {
    return {
        ...current,
        response: current.response ? { ...current.response } : null
    };
}

function emit() {
    const snapshot = cloneState(state);
    listeners.forEach((listener) => listener(snapshot));
}

function setState(nextState: OracleCommandState | ((current: OracleCommandState) => OracleCommandState)) {
    state = typeof nextState === 'function' ? nextState(state) : nextState;
    emit();
}

function clearTimeoutSafe(timer: number | null) {
    if (timer !== null) {
        globalThis.clearTimeout(timer);
    }
}

function clearIntervalSafe(timer: number | null) {
    if (timer !== null) {
        globalThis.clearInterval(timer);
    }
}

function stopTimers() {
    clearTimeoutSafe(phaseTimer);
    clearTimeoutSafe(staleSoftTimer);
    clearTimeoutSafe(staleHardTimer);
    clearIntervalSafe(tickInterval);
    phaseTimer = null;
    staleSoftTimer = null;
    staleHardTimer = null;
    tickInterval = null;
}

function isActivePhase(phase: OracleCommandPhase) {
    return phase === 'submitted' || phase === 'deliberating' || phase === 'stale';
}

function getElapsedMs(submittedAt: number | null, fallback = 0) {
    return submittedAt ? Math.max(0, Date.now() - submittedAt) : fallback;
}

function startElapsedClock(requestId: string) {
    clearIntervalSafe(tickInterval);
    tickInterval = globalThis.setInterval(() => {
        setState((current) => {
            if (current.requestId !== requestId || !current.submittedAt || !isActivePhase(current.phase)) {
                clearIntervalSafe(tickInterval);
                tickInterval = null;
                return current;
            }
            return {
                ...current,
                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
            };
        });
    }, 250);
}

function schedulePhaseTimers(requestId: string) {
    phaseTimer = globalThis.setTimeout(() => {
        setState((current) => {
            if (current.requestId !== requestId || current.phase !== 'submitted') {
                return current;
            }
            return {
                ...current,
                phase: 'deliberating',
                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
            };
        });
    }, ORACLE_COMMAND_BUDGETS_MS.deliberationDelay);

    staleSoftTimer = globalThis.setTimeout(() => {
        setState((current) => {
            if (current.requestId !== requestId || !isActivePhase(current.phase)) {
                return current;
            }
            return {
                ...current,
                phase: 'stale',
                staleLevel: 'soft',
                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
            };
        });
    }, ORACLE_COMMAND_BUDGETS_MS.staleSoft);

    staleHardTimer = globalThis.setTimeout(() => {
        setState((current) => {
            if (current.requestId !== requestId || !isActivePhase(current.phase)) {
                return current;
            }
            return {
                ...current,
                phase: 'stale',
                staleLevel: 'hard',
                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
            };
        });
    }, ORACLE_COMMAND_BUDGETS_MS.staleHard);
}

function hardTimeoutForMode(mode: OracleCommandMode) {
    return mode === 'council'
        ? ORACLE_COMMAND_BUDGETS_MS.councilHardTimeout
        : ORACLE_COMMAND_BUDGETS_MS.directHardTimeout;
}

function makeRequestId() {
    requestCounter += 1;
    return `oracle_${Date.now()}_${requestCounter}`;
}

function normalizeError(error: unknown) {
    if (error instanceof Error) {
        return error.message || 'ORACLE_COMMAND_FAILED';
    }
    if (typeof error === 'string' && error.trim()) {
        return error.trim();
    }
    return 'ORACLE_COMMAND_FAILED';
}

function settleRequest(requestId: string, phase: 'completed' | 'failed', patch: Partial<OracleCommandState>) {
    stopTimers();
    setState((current) => {
        if (current.requestId !== requestId) return current;
        const settledAt = Date.now();
        return {
            ...current,
            ...patch,
            phase,
            settledAt,
            elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
        };
    });
}

export function getOracleCommandState() {
    return cloneState(state);
}

export function subscribeOracleCommandState(listener: OracleCommandListener) {
    listeners.add(listener);
    listener(getOracleCommandState());
    return () => {
        listeners.delete(listener);
    };
}

export function resetOracleCommandState() {
    stopTimers();
    activeController?.abort();
    activeController = null;
    setState(createIdleState());
}

export type OracleStreamCallback = (chunk: { type: 'token' | 'done' | 'error'; token?: string; content?: string; error?: string }) => void;

export async function submitOracleCommandStream(
    options: OracleSubmitOptions & { onChunk: OracleStreamCallback; modelId?: string }
) {
    const command = options.command.trim();
    if (!command) throw new Error('ORACLE_COMMAND_REQUIRED');

    stopTimers();
    activeController?.abort();
    const requestId = makeRequestId();
    const submittedAt = Date.now();
    const controller = new AbortController();
    activeController = controller;

    setState({
        requestId,
        source: options.source || 'typed',
        mode: 'direct',
        phase: 'submitted',
        staleLevel: null,
        command,
        response: null,
        error: null,
        submittedAt,
        settledAt: null,
        elapsedMs: 0
    });

    startElapsedClock(requestId);
    schedulePhaseTimers(requestId);

    const model = options.modelId || 'qwen-liberated:latest';
    const url = `/api/oracle/stream?command=${encodeURIComponent(command)}&model=${encodeURIComponent(model)}`;
    const es = new EventSource(url);
    let full = '';

    es.addEventListener('token', (e: MessageEvent) => {
        try {
            const { token } = JSON.parse(e.data);
            full += token;
            options.onChunk({ type: 'token', token });
        } catch (_) {}
    });

    es.addEventListener('done', (e: MessageEvent) => {
        es.close();
        try { const { content } = JSON.parse(e.data); full = content || full; } catch (_) {}
        options.onChunk({ type: 'done', content: full });
        settleRequest(requestId, 'completed', { response: { content: full }, error: null });
    });

    es.addEventListener('error', (e: MessageEvent) => {
        es.close();
        let msg = 'STREAM_FAILED';
        try { msg = JSON.parse((e as any).data)?.message || msg; } catch (_) {}
        options.onChunk({ type: 'error', error: msg });
        settleRequest(requestId, 'failed', { response: null, error: msg });
    });

    es.onerror = () => {
        es.close();
        settleRequest(requestId, 'failed', { response: null, error: 'SSE_CONNECTION_LOST' });
    };
}

export async function submitOracleCommand(options: OracleSubmitOptions) {
    const command = options.command.trim();
    if (!command) {
        throw new Error('ORACLE_COMMAND_REQUIRED');
    }

    stopTimers();
    activeController?.abort();

    const requestId = makeRequestId();
    const submittedAt = Date.now();
    const mode: OracleCommandMode = options.useCouncil ? 'council' : 'direct';
    const controller = new AbortController();
    const upstreamSignal = options.signal;
    const relayAbort = () => controller.abort();

    if (upstreamSignal) {
        if (upstreamSignal.aborted) {
            controller.abort();
        } else {
            upstreamSignal.addEventListener('abort', relayAbort, { once: true });
        }
    }

    activeController = controller;

    setState({
        requestId,
        source: options.source || 'typed',
        mode,
        phase: 'submitted',
        staleLevel: null,
        command,
        response: null,
        error: null,
        submittedAt,
        settledAt: null,
        elapsedMs: 0
    });

    startElapsedClock(requestId);
    schedulePhaseTimers(requestId);

    try {
        const response = await apiFetchWithTimeout(ORACLE_COMMAND_ENDPOINT, hardTimeoutForMode(mode), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                command,
                useCouncil: mode === 'council',
                modelId: mode === 'direct' ? options.modelId || undefined : undefined
            }),
            signal: controller.signal
        });

        const payload = await response.json().catch(() => ({} as OracleCommandResponse));
        if (!response.ok) {
            const message = String(
                (payload as Record<string, unknown>)?.message
                || (payload as Record<string, unknown>)?.error
                || `HTTP_${response.status}`
            );
            throw new Error(message);
        }

        settleRequest(requestId, 'completed', {
            response: payload,
            error: null
        });
        return payload;
    } catch (error) {
        if (state.requestId === requestId) {
            settleRequest(requestId, 'failed', {
                response: null,
                error: normalizeError(error)
            });
        }
        throw error;
    } finally {
        if (upstreamSignal) {
            upstreamSignal.removeEventListener('abort', relayAbort);
        }
        if (activeController === controller) {
            activeController = null;
        }
    }
}

import { spawn } from 'child_process';
import Database from 'better-sqlite3';
import { logEvent } from '../models/queries';
import { SystemConfig } from '../config/SystemConfig';
import { runVaultIngestion } from './vaultIngestion';
import { syncOutlookIcs } from './outlookIcs';
import { syncPlaneTickets } from './planeSync';

export type AllowedCommandKey =
    | 'GITNEXUS_ANALYZE'
    | 'PALACE_REBUILD'
    | 'VAULT_INGEST'
    | 'SYSTEM_UPDATE'
    | 'PLANE_SYNC'
    | 'OUTLOOK_SYNC'
    | 'OPEN_IMAGES_FOLDER';

type CommandExecutionResult = {
    stdout: string;
    stderr: string;
    exitCode: number;
};

type SpawnCommand = {
    kind: 'spawn';
    command: string;
    args: string[];
};

type HandlerCommand = {
    kind: 'handler';
    run: (db: Database.Database) => Promise<CommandExecutionResult>;
};

type AllowedCommand = SpawnCommand | HandlerCommand;

export const ALLOWED_COMMANDS: Record<AllowedCommandKey, { description: string }> = {
    GITNEXUS_ANALYZE: { description: 'Refresh the GitNexus index for this repository.' },
    PALACE_REBUILD: { description: 'Run the palace rebuild maintenance script.' },
    VAULT_INGEST: { description: 'Trigger a vault ingestion pass without shelling out.' },
    SYSTEM_UPDATE: { description: 'Pull the latest git changes from the configured remote.' },
    PLANE_SYNC: { description: 'Synchronize tickets from Plane.so.' },
    OUTLOOK_SYNC: { description: 'Synchronize calendar events from the Outlook ICS feed.' },
    OPEN_IMAGES_FOLDER: { description: 'Open the generated images folder in Finder.' }
};

const COMMAND_HANDLERS: Record<AllowedCommandKey, AllowedCommand> = {
    GITNEXUS_ANALYZE: { kind: 'spawn', command: 'npx', args: ['gitnexus', 'analyze'] },
    PALACE_REBUILD: { kind: 'spawn', command: 'python3', args: [SystemConfig.resolve('_SYSTEM/palace-rebuild.py')] },
    SYSTEM_UPDATE: { kind: 'spawn', command: 'git', args: ['pull'] },
    OPEN_IMAGES_FOLDER: { kind: 'spawn', command: 'open', args: [SystemConfig.resolve('../GeneratedContent/images')] },
    VAULT_INGEST: {
        kind: 'handler',
        async run(db) {
            const result = await runVaultIngestion(db, 'executor:VAULT_INGEST');
            return {
                stdout: JSON.stringify(result),
                stderr: '',
                exitCode: result.failureRate > 10 ? 1 : 0
            };
        }
    },
    PLANE_SYNC: {
        kind: 'handler',
        async run() {
            const result = await syncPlaneTickets();
            return {
                stdout: JSON.stringify(result),
                stderr: '',
                exitCode: result.success ? 0 : 1
            };
        }
    },
    OUTLOOK_SYNC: {
        kind: 'handler',
        async run() {
            await syncOutlookIcs();
            return {
                stdout: 'Outlook sync completed.',
                stderr: '',
                exitCode: 0
            };
        }
    }
};

function runSpawnCommand(command: string, args: string[]): Promise<CommandExecutionResult> {
    return new Promise((resolve, reject) => {
        const child = spawn(command, args, {
            cwd: SystemConfig.ROOT,
            shell: false,
            env: process.env
        });

        let stdout = '';
        let stderr = '';

        child.stdout.on('data', (chunk) => {
            stdout += chunk.toString();
        });

        child.stderr.on('data', (chunk) => {
            stderr += chunk.toString();
        });

        child.on('error', reject);
        child.on('close', (code) => {
            const exitCode = code ?? 1;
            if (exitCode !== 0) {
                reject(new Error(stderr.trim() || `${command} exited with code ${exitCode}`));
                return;
            }

            resolve({ stdout, stderr, exitCode });
        });
    });
}

export function isAllowedCommandKey(value: string): value is AllowedCommandKey {
    return value in COMMAND_HANDLERS;
}

export async function executeCommand(
    db: Database.Database,
    commandKey: AllowedCommandKey,
    source: string = 'SYSTEM'
): Promise<CommandExecutionResult> {
    const selectedCommand = COMMAND_HANDLERS[commandKey];

    console.log(`⬡ EXECUTOR :: RUNNING -> ${commandKey}`);
    logEvent(db, 'SYSTEM', 'EXECUTOR', `Executing command key: ${commandKey} (${source})`, 'INFO');

    try {
        const result = selectedCommand.kind === 'spawn'
            ? await runSpawnCommand(selectedCommand.command, selectedCommand.args)
            : await selectedCommand.run(db);

        if (result.stderr) {
            console.error(`⬡ EXECUTOR_ERROR :: ${result.stderr}`);
            logEvent(db, 'SYSTEM', 'EXECUTOR', `Command warning (${commandKey}): ${result.stderr.slice(0, 200)}`, 'WARN');
        }

        return result;
    } catch (error: any) {
        console.error(`⬡ EXECUTOR_CRITICAL :: ${error.message}`);
        logEvent(db, 'SYSTEM', 'EXECUTOR', `Execution failed for ${commandKey}: ${error.message.slice(0, 200)}`, 'CRITICAL');
        throw error;
    }
}

